package com.vynedam.stockai.model; import com.vynedam.stockai.domain.PurchaseOrderStatus; import java.util.List; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document;
@Document("purchase_orders") public class PurchaseOrder extends BaseDocument{@Id public String id;@Indexed(unique=true)public String poNumber;public String supplierId;public PurchaseOrderStatus status;public List<Line> lines;public String createdBy;public static class Line{public String materialId;public double quantity;public double unitPrice;}}
